svg.script:
(function () {
'use strict';
/* ==================== 1. helpers ==================== */
const NS = 'http://www.w3.org/2000/svg', svg = document.documentElement, W = 1280, H = 720;
const $ = (id) => document.getElementById(id);
function el(tag, attrs, parent) {
  const n = document.createElementNS(NS, tag);
  if (attrs) for (const k in attrs) n.setAttribute(k, attrs[k]);
  if (parent) parent.appendChild(n);
  return n;
}
function vis(n, on) { const v = on ? 'inline' : 'none'; if (n.__v !== v) { n.__v = v; n.setAttribute('display', v); } }
const rand = (a, b) => a + Math.random() * (b - a);
const irand = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
const pick = (a) => a[Math.floor(Math.random() * a.length)];
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const easeOut = (t) => 1 - (1 - t) * (1 - t);
const r1 = (v) => Math.round(v * 10) / 10;
const KEY = 'opus_showcase_fruit-slash_best';
function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
function lsSet(k, v) { try { localStorage.setItem(k, String(v)); } catch (e) { /* storage blocked */ } }

/* ==================== 2. audio (all synthesized) ==================== */
const Snd = (() => {
  let ac = null, master, sfx, mus, nbuf, hissG, hissOn = false, muted = lsGet(KEY + '_muted') === '1';
  function init() {
    if (ac) { if (ac.state === 'suspended') ac.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      ac = new AC();
      master = ac.createGain(); master.gain.value = muted ? 0 : 0.85;
      const comp = ac.createDynamicsCompressor(); comp.threshold.value = -12; comp.ratio.value = 4;
      master.connect(comp); comp.connect(ac.destination);
      sfx = ac.createGain(); sfx.gain.value = 0.9; sfx.connect(master);
      mus = ac.createGain(); mus.gain.value = 0.5; mus.connect(master);
      const dl = ac.createDelay(1), fb = ac.createGain(), lp = ac.createBiquadFilter();
      dl.delayTime.value = 0.33; fb.gain.value = 0.35; lp.type = 'lowpass'; lp.frequency.value = 1800;
      mus.connect(dl); dl.connect(lp); lp.connect(fb); fb.connect(dl); lp.connect(master);
      nbuf = ac.createBuffer(1, (ac.sampleRate * 1.5) | 0, ac.sampleRate);
      const d = nbuf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      const hs = ac.createBufferSource(), hp = ac.createBiquadFilter();
      hs.buffer = nbuf; hs.loop = true; hp.type = 'highpass'; hp.frequency.value = 3800;
      hissG = ac.createGain(); hissG.gain.value = 0;
      hs.connect(hp); hp.connect(hissG); hissG.connect(sfx); hs.start();
      if (ac.state === 'suspended') ac.resume().catch(() => {});
    } catch (e) { ac = null; }
  }
  function env(g, t0, a, pk, dec) {
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(pk, t0 + a);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + a + dec);
  }
  function nz(dur, type, f0, f1, q, pk, a, t0, dest) {
    const s = ac.createBufferSource(), f = ac.createBiquadFilter(), g = ac.createGain();
    s.buffer = nbuf; f.type = type; f.frequency.setValueAtTime(f0, t0);
    if (f1) f.frequency.exponentialRampToValueAtTime(f1, t0 + a + dur);
    f.Q.value = q; env(g, t0, a, pk, dur);
    s.connect(f); f.connect(g); g.connect(dest || sfx);
    s.start(t0, Math.random()); s.stop(t0 + a + dur + 0.05);
  }
  function tn(type, f0, f1, dur, pk, a, t0, dest) {
    const o = ac.createOscillator(), g = ac.createGain();
    o.type = type; o.frequency.setValueAtTime(f0, t0);
    if (f1) o.frequency.exponentialRampToValueAtTime(f1, t0 + a + dur);
    env(g, t0, a, pk, dur); o.connect(g); g.connect(dest || sfx);
    o.start(t0); o.stop(t0 + a + dur + 0.05);
  }
  // koto-like pluck: detuned saw + octave triangle through a closing lowpass
  function pl(freq, vol, t0, dest) {
    const o = ac.createOscillator(), o2 = ac.createOscillator(), lp = ac.createBiquadFilter(), g = ac.createGain(), g2 = ac.createGain();
    o.type = 'sawtooth'; o.frequency.setValueAtTime(freq * 1.015, t0); o.frequency.exponentialRampToValueAtTime(freq, t0 + 0.05);
    o2.type = 'triangle'; o2.frequency.value = freq * 2.003; g2.gain.value = 0.35;
    lp.type = 'lowpass'; lp.Q.value = 3;
    lp.frequency.setValueAtTime(Math.min(9000, freq * 9), t0); lp.frequency.exponentialRampToValueAtTime(freq * 1.4, t0 + 0.4);
    g.gain.setValueAtTime(0.0001, t0); g.gain.exponentialRampToValueAtTime(vol, t0 + 0.005);
    g.gain.exponentialRampToValueAtTime(vol * 0.28, t0 + 0.2); g.gain.exponentialRampToValueAtTime(0.0001, t0 + 1.8);
    o.connect(lp); o2.connect(g2); g2.connect(lp); lp.connect(g); g.connect(dest || mus);
    o.start(t0); o2.start(t0); o.stop(t0 + 1.9); o2.stop(t0 + 1.9);
  }
  const SC = [146.83, 220, 293.66, 311.13, 392, 440, 466.16, 587.33, 622.25, 783.99]; // D miyako-bushi
  function play(fn) { if (!ac || muted) return; try { fn(ac.currentTime); } catch (e) { /* audio is optional */ } }
  return {
    init,
    get muted() { return muted; },
    setMuted(m) {
      muted = m; lsSet(KEY + '_muted', m ? 1 : 0);
      if (ac) try { master.gain.setTargetAtTime(m ? 0 : 0.85, ac.currentTime, 0.03); } catch (e) { /* ignore */ }
    },
    whoosh: (sp) => play((t) => { const f = clamp(500 + sp * 0.3, 650, 2600); nz(0.16, 'bandpass', f * 0.6, f * 1.6, 1.2, clamp(0.06 + sp / 14000, 0.06, 0.28), 0.03, t); }),
    slice: (sz, v) => play((t) => { v = v || 1; nz(0.06, 'highpass', 3500, 0, 0.8, 0.2 * v, 0.002, t); nz(0.15, 'bandpass', 1200 - sz * 400, 250, 3.2, 0.45 * v, 0.004, t + 0.004); tn('sine', 240 - sz * 80, 70, 0.12, 0.3 * v, 0.003, t); }),
    crit: () => play((t) => { tn('sine', 2640, 2380, 0.5, 0.14, 0.004, t); tn('triangle', 1760, 0, 0.6, 0.1, 0.004, t + 0.02); nz(0.3, 'highpass', 6000, 0, 0.7, 0.12, 0.003, t); }),
    boom: (big) => play((t) => { nz(big ? 1.5 : 0.7, 'lowpass', big ? 2600 : 1800, 90, 0.8, big ? 0.95 : 0.6, 0.005, t); tn('sine', big ? 120 : 150, 28, big ? 1 : 0.5, big ? 0.9 : 0.55, 0.005, t); nz(0.3, 'highpass', 2600, 0, 0.7, 0.3, 0.002, t); }),
    fuse: () => play((t) => { tn('sawtooth', 300, 1400, 0.6, 0.08, 0.02, t); nz(0.6, 'bandpass', 2000, 7000, 2, 0.25, 0.05, t); }),
    gong: () => play((t) => {
      [[1, 0.45, 4.5], [1.006, 0.2, 4], [1.49, 0.24, 3.2], [2.02, 0.2, 2.6], [2.76, 0.12, 2], [3.43, 0.08, 1.6], [4.2, 0.06, 1.2]].forEach(([r, v, d]) => {
        const o = ac.createOscillator(), g = ac.createGain();
        o.frequency.setValueAtTime(98 * r * 1.03, t); o.frequency.exponentialRampToValueAtTime(98 * r, t + 0.3);
        g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(v, t + 0.015); g.gain.exponentialRampToValueAtTime(0.0001, t + d);
        o.connect(g); g.connect(sfx); o.start(t); o.stop(t + d + 0.1);
      });
      nz(0.2, 'lowpass', 500, 150, 1, 0.35, 0.004, t);
    }),
    tick: (hi) => play((t) => { tn('sine', hi ? 1250 : 880, hi ? 1000 : 700, 0.07, 0.28, 0.002, t); nz(0.04, 'bandpass', hi ? 3000 : 2200, 0, 5, 0.18, 0.001, t); }),
    miss: () => play((t) => { tn('sine', 160, 70, 0.45, 0.45, 0.004, t); nz(0.25, 'lowpass', 500, 120, 1, 0.3, 0.004, t); pl(146.83, 0.25, t + 0.02, sfx); }),
    combo: (n) => play((t) => { for (let i = 0; i < Math.min(n, 7); i++) pl(SC[2 + (i % 8)], 0.28, t + i * 0.065, sfx); }),
    freeze: () => play((t) => { for (let i = 0; i < 6; i++) tn('sine', 2000 + Math.random() * 2400, 0, 0.35, 0.07, 0.003, t + i * 0.05); nz(0.8, 'bandpass', 5000, 800, 4, 0.2, 0.05, t); }),
    double: () => play((t) => { [659, 880, 1318].forEach((f, i) => pl(f, 0.3, t + i * 0.08, sfx)); }),
    frenzy: () => play((t) => { for (let i = 0; i < 6; i++) tn('sine', 95, 48, 0.22, 0.55, 0.003, t + i * 0.07); nz(0.5, 'lowpass', 900, 200, 1, 0.3, 0.01, t); }),
    ready: () => play((t) => { tn('sine', 110, 60, 0.5, 0.7, 0.004, t); nz(0.2, 'lowpass', 400, 100, 1, 0.4, 0.003, t); }),
    go: () => play((t) => { tn('sine', 90, 40, 0.7, 0.9, 0.004, t); nz(0.25, 'bandpass', 1400, 4000, 1.2, 0.3, 0.02, t); }),
    fanfare: () => play((t) => { [293.66, 392, 440, 587.33, 783.99, 880].forEach((f, i) => pl(f, 0.3, t + i * 0.09, sfx)); }),
    ui: () => play((t) => { tn('sine', 980, 760, 0.05, 0.2, 0.002, t); }),
    phrase: (arr) => play((t) => { arr.forEach((n, i) => pl(SC[n], 0.17 * (1 - i * 0.15), t + i * 0.27)); }),
    hiss(on) {
      on = on && !muted;
      if (on === hissOn || !ac || !hissG) return;
      hissOn = on;
      try { hissG.gain.setTargetAtTime(on ? 0.045 : 0, ac.currentTime, 0.05); } catch (e) { /* ignore */ }
    }
  };
})();

/* ==================== 3. data ==================== */
const FR = {
  watermelon: { r: 58, j: '#e8323c', j2: '#ff8080', s: '#a8141e' },
  orange: { r: 40, j: '#ff9a1f', j2: '#ffc766', s: '#c85f00' },
  apple: { r: 38, j: '#f6e7a8', j2: '#fff8dc', s: '#a88a3a' },
  pineapple: { r: 42, j: '#ffd23f', j2: '#fff08a', s: '#b88a0a' },
  banana: { r: 42, j: '#fff1a8', j2: '#fffbe0', s: '#a8903a' },
  strawberry: { r: 31, j: '#e0203a', j2: '#ff7a8a', s: '#9a0c20' },
  kiwi: { r: 33, j: '#8fd13f', j2: '#d4f58a', s: '#4a7a14' },
  coconut: { r: 42, j: '#f7f3ea', j2: '#ffffff', s: '#b8ae98' },
  peach: { r: 38, j: '#ffb36b', j2: '#ffe0a8', s: '#c8642a' },
  lemon: { r: 34, j: '#fff04f', j2: '#fffbc0', s: '#b0a010' },
  freeze: { r: 42, j: '#8fe6ff', j2: '#e6fbff', s: '#3a8ab8', sp: 1 },
  double: { r: 42, j: '#ffd84a', j2: '#fff5c8', s: '#b88a00', sp: 1 },
  frenzy: { r: 42, j: '#ff6a2a', j2: '#ffd0b0', s: '#b0300a', sp: 1 }
};
const TYPES = ['watermelon', 'orange', 'apple', 'pineapple', 'banana', 'strawberry', 'kiwi', 'coconut', 'peach', 'lemon'];
const SPEC = {
  freeze: { t: 5, label: '冰冻', c: '#8fe6ff', aura: 'url(#gAuraIce)' },
  double: { t: 7, label: '双倍', c: '#ffd84a', aura: 'url(#gAuraGold)' },
  frenzy: { t: 5, label: '狂热', c: '#ff7a3a', aura: 'url(#gAuraFire)' }
};
const MODES = [
  { key: 'classic', name: '经典', time: 0, bombs: 1, lives: 3, ramp: 110, im: 1, sp: 0 },
  { key: 'arcade', name: '街机', time: 60, bombs: 1, lives: 0, ramp: 60, im: 0.78, sp: 1 },
  { key: 'zen', name: '禅意', time: 90, bombs: 0, lives: 0, ramp: 90, im: 0.82, sp: 0 }
];
// interval i0->i1, volley size v0->v1 and bomb chance b0->b1 ramp over MODES.ramp seconds
const DIFF = [
  { name: '简单', g: 980, i0: 1.85, i1: 1.15, v0: 2, v1: 4, b0: 0.07, b1: 0.14, apex: [170, 330], pats: { single: 5, volley: 3, arc: 2, burst: 1 } },
  { name: '普通', g: 1120, i0: 1.5, i1: 0.9, v0: 2, v1: 5, b0: 0.11, b1: 0.2, apex: [120, 300], pats: { single: 3, volley: 4, arc: 3, burst: 2, cross: 2 } },
  { name: '困难', g: 1280, i0: 1.2, i1: 0.68, v0: 3, v1: 7, b0: 0.16, b1: 0.28, apex: [90, 280], pats: { single: 2, volley: 4, arc: 3, burst: 3, cross: 3, side: 2, rapid: 2 } }
];
const CN = ['', '一', '二', '三', '四', '五', '六', '七', '八', '九', '十'];
const SLICE_SPEED = 520, TRAIL_LIFE = 110;
let G = 1120;

/* ==================== 4. pools ==================== */
const Lr = { dec: $('decalsL'), sh: $('shadowsL'), hv: $('halvesL'), en: $('entsL'), dr: $('dropsL'), fx: $('fxL'), gh: $('ghostL'), pp: $('popupsL'), mf: $('menuFxL'), bl: $('bladeL') };

// fruits, bombs and special bananas in flight
const ENTS = [];
for (let i = 0; i < 34; i++) {
  const g = el('g', { display: 'none' }, Lr.en);
  const aura = el('circle', { r: 60, display: 'none' }, g);
  const rot = el('g', null, g);
  const use = el('use', null, rot);
  const spark = el('use', { href: '#spark', display: 'none' }, rot);
  const label = el('text', { class: 'br stroke', 'font-size': 18, 'text-anchor': 'middle', y: 66, stroke: '#1a0d05', 'stroke-width': 4, display: 'none' }, g);
  const sh = el('circle', { cx: 9, cy: 15, fill: 'url(#gShadow)', display: 'none' }, Lr.sh);
  ENTS.push({ g, aura, rot, use, spark, label, sh, on: false });
}
function spawnEnt(type, x, y, vx, vy, o) {
  let e = null;
  for (const q of ENTS) if (!q.on) { e = q; break; }
  if (!e) return null;
  o = o || {};
  const bomb = type === 'bomb', F = FR[type];
  e.on = true; e.type = type; e.bomb = bomb; e.sp = !bomb && F.sp ? type : null;
  e.r = bomb ? 34 : F.r; e.x = x; e.y = y; e.vx = vx; e.vy = vy;
  e.a = rand(-40, 40); e.va = rand(70, 220) * (Math.random() < 0.5 ? -1 : 1);
  e.age = 0; e.float = !!o.float; e.entered = false; e.demo = !!o.demo; e.nomiss = !!o.nomiss; e.ghosted = false;
  e.use.setAttribute('href', '#f-' + type);
  vis(e.spark, bomb);
  if (bomb || e.sp) { e.aura.setAttribute('fill', bomb ? 'url(#gAuraRed)' : SPEC[type].aura); e.aura.setAttribute('r', bomb ? 62 : 68); }
  vis(e.aura, bomb || !!e.sp);
  if (e.sp) { e.label.textContent = SPEC[type].label; e.label.setAttribute('fill', SPEC[type].c); }
  vis(e.label, !!e.sp);
  e.sh.setAttribute('r', r1(e.r * 1.08));
  vis(e.g, true); vis(e.sh, true);
  placeEnt(e);
  return e;
}
function placeEnt(e) {
  const tx = 'translate(' + r1(e.x) + ' ' + r1(e.y) + ')';
  e.g.setAttribute('transform', tx); e.sh.setAttribute('transform', tx);
  e.rot.setAttribute('transform', 'rotate(' + r1(e.a) + ')');
}
function killEnt(e) { e.on = false; vis(e.g, false); vis(e.sh, false); }

// sliced halves: outer spin frame -> half-plane clip of the skin + the cut face squashed toward the chord
function makeHalves(layer, n) {
  const a = [];
  for (let i = 0; i < n; i++) {
    const g = el('g', { display: 'none' }, layer), rot = el('g', null, g), clip = el('g', null, rot), cr = el('g', null, clip);
    const skin = el('use', null, cr), clip2 = el('g', null, rot), sq = el('g', null, clip2), fr = el('g', null, sq), face = el('use', null, fr);
    a.push({ g, rot, clip, clip2, cr, skin, sq, fr, face, on: false, t: 0 });
  }
  return a;
}
const HALVES = makeHalves(Lr.hv, 64), MHALVES = makeHalves(Lr.mf, 8);
function spawnHalf(pool, type, x, y, vx, vy, phi, theta, top, vs, s) {
  let h = null, old = null;
  for (const q of pool) { if (!q.on) { h = q; break; } if (!old || q.t > old.t) old = q; }
  if (!h) h = old;
  Object.assign(h, { on: true, x, y, vx, vy, phi, spin: 0, vs, t: 0, k: -1, s: s || 1 });
  const cp = top ? 'url(#cTop)' : 'url(#cBot)';
  h.clip.setAttribute('clip-path', cp); h.clip2.setAttribute('clip-path', cp);
  const cr = 'rotate(' + r1(theta - phi) + ')';
  h.cr.setAttribute('transform', cr); h.fr.setAttribute('transform', cr);
  h.skin.setAttribute('href', '#f-' + type); h.face.setAttribute('href', '#x-' + type);
  vis(h.g, true);
  return h;
}
function updHalves(pool, dt) {
  for (const h of pool) {
    if (!h.on) continue;
    h.t += dt; h.vy += G * dt; h.x += h.vx * dt; h.y += h.vy * dt; h.spin += h.vs * dt;
    if (h.y > H + 150 || h.t > 5) { h.on = false; vis(h.g, false); continue; }
    h.g.setAttribute('transform', 'translate(' + r1(h.x) + ' ' + r1(h.y) + ')' + (h.s !== 1 ? ' scale(' + h.s + ')' : ''));
    h.rot.setAttribute('transform', 'rotate(' + r1(h.phi + h.spin) + ')');
    const k = Math.min(0.84, 0.16 + h.t * 3);
    if (k !== h.k) { h.k = k; h.sq.setAttribute('transform', 'scale(1 ' + k.toFixed(3) + ')'); }
  }
}

// juice droplets, sparks and smoke puffs (ring buffers)
function makeDrops(layer, n) { const a = []; for (let i = 0; i < n; i++) a.push({ c: el('circle', { r: 1, display: 'none' }, layer), on: false }); return a; }
const DROPS = makeDrops(Lr.dr, 170), MDROPS = makeDrops(Lr.mf, 40);
let dropI = 0, mdropI = 0;
function drop(x, y, vx, vy, r, col, life, g, smoke, menu) {
  let d;
  if (menu) { d = MDROPS[mdropI]; mdropI = (mdropI + 1) % MDROPS.length; } else { d = DROPS[dropI]; dropI = (dropI + 1) % DROPS.length; }
  d.on = true; d.x = x; d.y = y; d.vx = vx; d.vy = vy; d.r = r; d.life = d.max = life; d.g = g; d.smoke = !!smoke;
  d.c.setAttribute('fill', col); d.c.setAttribute('opacity', smoke ? 0.5 : 0.95); vis(d.c, true);
}
function updDrops(pool, dt) {
  for (const d of pool) {
    if (!d.on) continue;
    d.life -= dt;
    if (d.life <= 0) { d.on = false; vis(d.c, false); continue; }
    d.vy += d.g * dt;
    if (d.smoke) { d.vx *= 0.96; d.vy *= 0.96; }
    d.x += d.vx * dt; d.y += d.vy * dt;
    const k = d.life / d.max, s = d.smoke ? d.r * (2.2 - k * 1.2) : d.r * Math.sqrt(k);
    d.c.setAttribute('transform', 'translate(' + r1(d.x) + ' ' + r1(d.y) + ') scale(' + s.toFixed(2) + ')');
    if (d.smoke) d.c.setAttribute('opacity', (0.5 * k).toFixed(2));
  }
}

// juice stains soaking into the board, slowly fading
const DECALS = [];
for (let i = 0; i < 60; i++) DECALS.push({ u: el('use', { display: 'none' }, Lr.dec), on: false });
let decI = 0, decAcc = 0;
function decal(x, y, col, sc, op, life) {
  const d = DECALS[decI]; decI = (decI + 1) % DECALS.length;
  d.on = true; d.age = 0; d.life = life || 14; d.op = op; d.cur = op;
  d.u.setAttribute('href', '#splat' + irand(0, 3)); d.u.setAttribute('fill', col); d.u.setAttribute('opacity', op);
  d.u.setAttribute('transform', 'translate(' + r1(x) + ' ' + r1(y) + ') rotate(' + irand(0, 359) + ') scale(' + sc.toFixed(2) + ')');
  vis(d.u, true);
}
function updDecals(dt) {
  decAcc += dt;
  if (decAcc < 0.15) return;
  const a = decAcc; decAcc = 0;
  for (const d of DECALS) {
    if (!d.on) continue;
    d.age += a;
    if (d.age >= d.life) { d.on = false; vis(d.u, false); continue; }
    const f = d.age < d.life * 0.45 ? 1 : 1 - (d.age - d.life * 0.45) / (d.life * 0.55);
    const o = Math.round(d.op * f * 100) / 100;
    if (Math.abs(o - d.cur) >= 0.01) { d.cur = o; d.u.setAttribute('opacity', o); }
  }
}

// one-shot tweened sprites: juice bursts, cut flashes, crit stars, blast rays, miss marks
const FXS = [];
for (let i = 0; i < 24; i++) FXS.push({ u: el('use', { display: 'none' }, Lr.fx), on: false });
let fxI = 0;
function tween(href, x, y, rot, sx0, sx1, sy0, sy1, op0, op1, dur, fill, vr) {
  const f = FXS[fxI]; fxI = (fxI + 1) % FXS.length;
  Object.assign(f, { on: true, x, y, rot, sx0, sx1, sy0, sy1, op0, op1, dur, t: 0, vr: vr || 0 });
  f.u.setAttribute('href', href); f.u.setAttribute('fill', fill); vis(f.u, true);
  applyTween(f, 0);
}
function applyTween(f, p) {
  const e = easeOut(p);
  f.u.setAttribute('transform', 'translate(' + r1(f.x) + ' ' + r1(f.y) + ') rotate(' + r1(f.rot + f.vr * f.t) + ') scale(' + lerp(f.sx0, f.sx1, e).toFixed(3) + ' ' + lerp(f.sy0, f.sy1, e).toFixed(3) + ')');
