// floating brush-text popups
const POPS = [];
for (let i = 0; i < 10; i++) {
  const g = el('g', { display: 'none' }, Lr.pp);
  const a = el('text', { class: 'br stroke', 'text-anchor': 'middle', stroke: '#2a1206', 'stroke-width': 6, 'font-weight': 700 }, g);
  const b = el('text', { class: 'nm stroke', 'text-anchor': 'middle', stroke: '#2a1206', 'stroke-width': 6, fill: '#fff6dc' }, g);
  POPS.push({ g, a, b, on: false });
}
let popI = 0;
function popup(x, y, t1, t2, col, size) {
  const p = POPS[popI]; popI = (popI + 1) % POPS.length;
  x = clamp(x, 140, W - 140); y = clamp(y, 120, H - 90);
  // move clear of any young popup that would overlap
  const free = (yy) => yy >= 110 && yy <= H - 90 && !POPS.some((q) => q.on && q !== p && q.t < 0.6 && Math.abs(q.x - x) < 190 && Math.abs(q.y - yy) < 62);
  const off = [0, -64, -128, 64, 128].find((o) => free(y + o));
  Object.assign(p, { on: true, x, y: y + (off || 0), t: 0, dur: 1.15 });
  const s = size || 34;
  p.a.textContent = t1; p.a.setAttribute('font-size', s); p.a.setAttribute('fill', col);
  p.b.textContent = t2 || ''; p.b.setAttribute('font-size', Math.round(s * 0.9)); p.b.setAttribute('y', Math.round(s * 0.95));
  vis(p.g, true);
}
function updPops(dt) {
  for (const p of POPS) {
    if (!p.on) continue;
    p.t += dt;
    const k = p.t / p.dur;
    if (k >= 1) { p.on = false; vis(p.g, false); continue; }
    const sc = k < 0.12 ? lerp(0.3, 1.18, k / 0.12) : k < 0.22 ? lerp(1.18, 1, (k - 0.12) / 0.1) : 1;
    p.g.setAttribute('transform', 'translate(' + r1(p.x) + ' ' + r1(p.y - 50 * easeOut(k)) + ') scale(' + sc.toFixed(3) + ')');
    p.g.setAttribute('opacity', (k > 0.72 ? 1 - (k - 0.72) / 0.28 : 1).toFixed(2));
  }
}

// blade trails: three stacked tapered ribbons (glow, halo, core)
function makeTrail(layer, w) {
