}
const trail = makeTrail(Lr.bl, 9), ghostTrail = makeTrail(Lr.gh, 8);
function trailAdd(tr, x, y, t) {
  const P = tr.pts, l = P[P.length - 1];
  if (l && Math.abs(l.x - x) + Math.abs(l.y - y) < 3) { l.t = t; return; }
  P.push({ x, y, t });
