}
function trailDraw(tr, now) {
  const P = tr.pts;
  while (P.length && now - P[0].t > TRAIL_LIFE) P.shift();
  const n = P.length;
  if (n < 2) {
    if (!tr.empty) { tr.empty = true; for (const p of tr.p) p.setAttribute('d', ''); }
    return;
  }
  tr.empty = false;
  const N = [];
  for (let i = 0; i < n; i++) {
    const a = P[Math.max(0, i - 1)], b = P[Math.min(n - 1, i + 1)];
    let dx = b.x - a.x, dy = b.y - a.y;
    const l = Math.hypot(dx, dy) || 1; dx /= l; dy /= l;
    const age = clamp(1 - (now - P[i].t) / TRAIL_LIFE, 0, 1), w = tr.w * (i / (n - 1)) * (0.35 + 0.65 * age);
    N.push(-dy * w, dx * w);
  }
  const hd = P[n - 1], pv = P[n - 2], hl = Math.hypot(hd.x - pv.x, hd.y - pv.y) || 1;
  const mul = [2.6, 1.5, 0.7];
  for (let k = 0; k < 3; k++) {
    const m = mul[k];
    let s = 'M' + r1(P[0].x) + ' ' + r1(P[0].y);
    for (let i = 1; i < n; i++) s += 'L' + r1(P[i].x + N[2 * i] * m) + ' ' + r1(P[i].y + N[2 * i + 1] * m);
    const tip = tr.w * m * 0.9;
    s += 'L' + r1(hd.x + (hd.x - pv.x) / hl * tip) + ' ' + r1(hd.y + (hd.y - pv.y) / hl * tip);
    for (let i = n - 1; i > 0; i--) s += 'L' + r1(P[i].x - N[2 * i] * m) + ' ' + r1(P[i].y - N[2 * i + 1] * m);
    tr.p[k].setAttribute('d', s + 'Z');
  }
}

/* ==================== 5. game state ==================== */
let state = 'title', helpFrom = 'title', pausedFrom = 'playing', mode = 0, diff = 1, selMode = 0, selDiff = 1;
let score = 0, shownScore = 0, bump = 0, misses = 0, fruitsSliced = 0, fruitsMissed = 0, streak = 0, bestStreak = 0, bestCombo = 0, crits = 0, bombsHit = 0;
let gameTime = 0, timeLeft = 0, spawnT = 0, specT = 0, frenzyT = 0, endT = 0, endReason = '', boomDone = false, gongDone = false, boomX = 0, boomY = 0, boomT = 0;
let cdT = 0, cdGo = false, shakeA = 0, flashA = 0, god = false, bot = false, botT = 0, realT = 0, lastType = '', menuPending = null, bombsOn = 0;
const pw = { freeze: 0, double: 0, frenzy: 0 };
const Q = [];
const combo = { n: 0, t: 0, x: 0, y: 0, src: '' };
const best = MODES.map((m) => +(lsGet(KEY + '_' + m.key) || 0) || 0);

/* ==================== 6. spawner ==================== */
const lvl = () => clamp(gameTime / MODES[mode].ramp, 0, 1);
function pickType() { let t; do { t = pick(TYPES); } while (t === lastType && Math.random() < 0.7); lastType = t; return t; }
// launch from below the screen so that the apex lands at (ax, ay)
function toss(type, x0, ax, ay, o) {
  const r = type === 'bomb' ? 34 : FR[type].r, y0 = H + r + 16;
  const vy = -Math.sqrt(2 * G * Math.max(120, y0 - ay)), T = -vy / G;
  return spawnEnt(type, x0, y0, (ax - x0) / T, vy, o);
}
function bombChance() { const D = DIFF[diff]; return !MODES[mode].bombs || gameTime < 4 ? 0 : lerp(D.b0, D.b1, lvl()); }
function apexY() { const a = DIFF[diff].apex; return rand(a[0], a[1]); }
function later(dt, fn) { Q.push({ t: gameTime + dt, fn }); }
function runQ() { for (let i = Q.length - 1; i >= 0; i--) if (Q[i].t <= gameTime) { const q = Q[i]; Q.splice(i, 1); q.fn(); } }
const maybeBomb = (k) => (Math.random() < bombChance() * k ? 'bomb' : pickType());
const PATS = {
  single() { const x0 = rand(200, 1080); toss(maybeBomb(0.8), x0, clamp(x0 + rand(-180, 180), 170, 1110), apexY()); },
  volley(n) {
    const span = Math.min(860, 175 * n), cx = rand(440, 840), maxB = n > 4 ? 2 : 1;
    let bombs = 0;
    for (let i = 0; i < n; i++) {
      const x0 = cx - span / 2 + span * (i + 0.5) / n + rand(-20, 20), b = bombs < maxB && i > 0 && Math.random() < bombChance();
      if (b) bombs++;
      toss(b ? 'bomb' : pickType(), x0, x0 + (x0 - cx) * 0.3 + rand(-30, 30), apexY());
    }
  },
  arc(n) {
    const dir = Math.random() < 0.5 ? 1 : -1, a = DIFF[diff].apex;
    for (let i = 0; i < n; i++) later(i * 0.2, () => {
      const f = (i + 0.5) / n, x0 = dir > 0 ? lerp(220, 1060, f) : lerp(1060, 220, f);
      toss(maybeBomb(0.6), x0, x0 + dir * 50, lerp(a[0], a[1], 0.3 + 1.4 * Math.abs(f - 0.5)));
    });
  },
  burst(n) { const x0 = rand(460, 820); for (let i = 0; i < n; i++) toss(i > 0 ? maybeBomb(0.7) : pickType(), x0 + rand(-14, 14), x0 + (i - (n - 1) / 2) * rand(95, 130), apexY()); },
  cross(n) {
    for (let i = 0; i < n; i++) later(i * 0.17, () => {
      const L = i % 2 === 0;
      toss(maybeBomb(0.6), L ? rand(130, 260) : rand(1020, 1150), L ? rand(720, 1000) : rand(280, 560), apexY());
    });
  },
  side(n) { const L = Math.random() < 0.5; for (let i = 0; i < n; i++) later(i * 0.24, () => spawnEnt(pickType(), L ? -50 : W + 50, rand(430, 600), (L ? 1 : -1) * rand(380, 520), -rand(620, 820))); },
  rapid(n) { for (let i = 0; i < n; i++) later(i * 0.14, PATS.single); }
};
function schedule() {
  const D = DIFF[diff], M = MODES[mode], l = lvl();
  let name = 'single';
  if (gameTime >= 3) {
    const wt = (k) => D.pats[k] * (k === 'single' ? 1 - l * 0.5 : 1 + l);
    let tot = 0;
    for (const k in D.pats) tot += wt(k);
    let r = Math.random() * tot;
    for (const k in D.pats) { r -= wt(k); if (r <= 0) { name = k; break; } }
  }
  const nMax = Math.round(lerp(D.v0, D.v1, l)) + (mode === 2 ? 1 : 0);
  let n = irand(Math.max(2, nMax - 2), Math.max(2, nMax));
  if (name === 'side') n = Math.min(n, 3);
  PATS[name](n);
  spawnT = lerp(D.i0, D.i1, l) * M.im * rand(0.85, 1.15) + ({ arc: 0.2, cross: 0.17, side: 0.24, rapid: 0.14 }[name] || 0) * n * 0.6;
}
function spawner(dt) {
  spawnT -= dt;
  if (spawnT <= 0) schedule();
  if (MODES[mode].sp) {
    specT -= dt;
    if (specT <= 0) { specT = rand(9, 14) - diff; const x0 = rand(300, 980); toss(pick(['freeze', 'double', 'frenzy']), x0, x0 + rand(-80, 80), rand(140, 260)); }
  }
  if (pw.frenzy > 0) {
    frenzyT -= dt;
    if (frenzyT <= 0) {
      frenzyT = rand(0.08, 0.13);
      const L = Math.random() < 0.5;
      spawnEnt(pickType(), L ? -50 : W + 50, rand(360, 640), (L ? 1 : -1) * rand(430, 720), -rand(560, 860), { nomiss: 1 });
    }
  }
  runQ();
}

/* ==================== 7. physics update ==================== */
function updEnts(dt) {
  let b = 0;
  for (const e of ENTS) {
    if (!e.on) continue;
    if (!e.float) e.vy += G * dt;
    e.x += e.vx * dt; e.y += e.vy * dt; e.a += e.va * dt; e.age += dt;
    if (!e.entered && e.y - e.r < H - 4 && e.x > -e.r && e.x < W + e.r) e.entered = true;
    if ((e.vy > 0 && e.y - e.r > H + 30) || e.x < -e.r - 220 || e.x > W + e.r + 220) {
      killEnt(e);
      if (!e.bomb && e.entered && !e.demo) onMiss(e);
      continue;
    }
    if (e.bomb) {
      b++;
      e.spark.setAttribute('transform', 'translate(18 -64) scale(' + (0.75 + Math.random() * 0.5).toFixed(2) + ') rotate(' + ((Math.random() * 90) | 0) + ')');
      if (Math.random() < dt * 14) {
        const c = Math.cos(e.a * Math.PI / 180), s = Math.sin(e.a * Math.PI / 180);
        drop(e.x + 18 * c + 64 * s, e.y + 18 * s - 64 * c, rand(-120, 120), rand(-200, 0), rand(1.5, 3), Math.random() < 0.5 ? '#fff3b0' : '#ffb347', rand(0.2, 0.4), 300);
      }
    }
    if (e.bomb || e.sp) e.aura.setAttribute('opacity', (0.65 + 0.35 * Math.sin(e.age * 9)).toFixed(2));
    placeEnt(e);
  }
  bombsOn = b;
}
function worldUpd(dt) { updEnts(dt); updHalves(HALVES, dt); updDrops(DROPS, dt); updFx(dt); updDecals(dt); }

/* ==================== 8. slicing & scoring ==================== */
function segDist2(px, py, ax, ay, bx, by) {
  const vx = bx - ax, vy = by - ay, l2 = vx * vx + vy * vy;
  let t = l2 > 0 ? ((px - ax) * vx + (py - ay) * vy) / l2 : 0;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  const qx = ax + vx * t - px, qy = ay + vy * t - py;
  return qx * qx + qy * qy;
}
function juice(x, y, ang, F, r, menu) {
  const n = Math.round(10 + r * 0.22);
  for (let i = 0; i < n; i++) {
    const side = Math.random() < 0.7 ? (Math.random() < 0.5 ? -1 : 1) * Math.PI / 2 : (Math.random() < 0.5 ? 0 : Math.PI);
    const a = ang + side + rand(-0.6, 0.6), sp = rand(120, 480);
    drop(x + rand(-6, 6), y + rand(-6, 6), Math.cos(a) * sp, Math.sin(a) * sp - rand(40, 160), rand(2.2, 6.5) * (r / 40), Math.random() < 0.65 ? F.j : F.j2, rand(0.4, 0.85), 900, false, menu);
  }
}
function sliceEnt(e, ang, speed, cd, scoring, quiet) {
  const F = FR[e.type], deg = ang * 180 / Math.PI, nx = -Math.sin(ang), ny = Math.cos(ang), ux = Math.cos(ang) * 30, sep = rand(80, 140);
  spawnHalf(HALVES, e.type, e.x - nx * 3, e.y - ny * 3, e.vx * 0.5 - nx * sep + ux, e.vy * 0.45 - ny * sep - 80, deg, e.a, true, -rand(80, 240));
  spawnHalf(HALVES, e.type, e.x + nx * 3, e.y + ny * 3, e.vx * 0.5 + nx * sep + ux, e.vy * 0.45 + ny * sep - 80, deg, e.a, false, rand(80, 240));
  juice(e.x, e.y, ang, F, e.r);
  decal(e.x + rand(-8, 8), e.y + rand(-8, 8), F.s, e.r / 34 * rand(0.85, 1.15), 0.6);
  const s = e.r / 40;
