function menuSlice(type, x, y, ang, sc) {
  const F = FR[type], deg = ang * 180 / Math.PI, nx = -Math.sin(ang), ny = Math.cos(ang);
  spawnHalf(MHALVES, type, x, y, -nx * 120, -ny * 120 - 120, deg, 0, true, -160, sc);
  spawnHalf(MHALVES, type, x, y, nx * 120, ny * 120 - 120, deg, 0, false, 160, sc);
