    addScore(n);
    popup(combo.x, combo.y - 40, (n <= 10 ? CN[n] : n) + '连击', '+' + (pw.double > 0 ? n * 2 : n), '#ffc43a', n >= 5 ? 42 : 34);
    Snd.combo(n); shake(3 + n);
  }
}
