function boomFx(x, y, big) {
  tween('#rays', x, y, rand(0, 360), 0.2, big ? 5 : 2.4, 0.2, big ? 5 : 2.4, 1, 0, big ? 1 : 0.6, 'url(#gRay)', 50);
  for (let i = 0; i < (big ? 14 : 8); i++) { const a = rand(0, 6.283), s = rand(40, 160); drop(x, y, Math.cos(a) * s, Math.sin(a) * s - 40, rand(10, 22), i % 2 ? '#3a332e' : '#5a4e44', rand(0.8, 1.4), -60, true); }
  for (let i = 0; i < 16; i++) { const a = rand(0, 6.283), s = rand(250, 650); drop(x, y, Math.cos(a) * s, Math.sin(a) * s, rand(2, 4), i % 3 ? '#ffcf6a' : '#fff4c0', rand(0.3, 0.6), 500); }
