  streak = 0; combo.n = 0; bombsHit++;
  if (MODES[mode].lives && !god) { gameOver('bomb', e.x, e.y); return; }
  boomFx(e.x, e.y, false);
  if (mode === 1) { score = Math.max(0, score - 10); popup(e.x, e.y - 40, '炸弹！', '-10', '#ff5a3a', 36); }
  for (const q of ENTS) {
    if (!q.on || q.bomb) continue;
    const dx = q.x - e.x, dy = q.y - e.y, d = Math.hypot(dx, dy) || 1;
