  if (state === 'playing') {
    for (const e of ENTS) {
      if (!e.on) continue;
      const rr = e.r * 0.92 + 6, d2 = segDist2(e.x, e.y, ax, ay, bx, by);
      if (d2 > rr * rr) continue;
