      if (state !== 'playing') return;
    }
  } else if (state === 'title' && !menuPending) {
    for (const e of ENTS) {
      if (!e.on) continue;
      const rr = e.r * 0.92 + 6;
      if (segDist2(e.x, e.y, ax, ay, bx, by) <= rr * rr) { killEnt(e); sliceEnt(e, ang, speed, 0, false); }
    }
    for (let i = 0; i < 3; i++) if (!RINGS[i].cut && segDist2(RINGS[i].x, RINGS[i].y, ax, ay, bx, by) <= 3600) { pickMode(i, ang); break; }
  } else if (state === 'over' && !menuPending) {
