function shake(a) { shakeA = Math.max(shakeA, a); }

/* ==================== 9. run flow ==================== */
function clearWorld() {
  for (const e of ENTS) if (e.on) killEnt(e);
  for (const h of HALVES) if (h.on) { h.on = false; vis(h.g, false); }
  for (const d of DROPS) if (d.on) { d.on = false; vis(d.c, false); }
  for (const p of POPS) if (p.on) { p.on = false; vis(p.g, false); }
  for (const f of FXS) if (f.on) { f.on = false; vis(f.u, false); }
  Q.length = 0; combo.n = 0; ghost.on = false; vis(boomG, false);
}
function startRun(m, d, skip) {
  mode = m; diff = d; selMode = m; selDiff = d; G = DIFF[d].g;
  clearWorld();
  score = shownScore = 0; misses = fruitsSliced = fruitsMissed = streak = bestStreak = bestCombo = crits = bombsHit = 0;
  gameTime = 0; timeLeft = MODES[m].time; spawnT = 0.8; specT = rand(6, 9); frenzyT = 0;
  pw.freeze = pw.double = pw.frenzy = 0; lastSec = -1; endT = 0; flashA = 0; menuPending = null; cdT = 0; cdGo = false;
  $('modeT').textContent = MODES[m].name + ' · ' + DIFF[d].name;
  vis($('livesG'), !!MODES[m].lives); vis($('timerG'), !!MODES[m].time); updLives(false);
