const KEYS = ['Enter', 'NumpadEnter', 'Space', 'Escape', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'KeyP', 'KeyM', 'KeyH', 'KeyR', 'Digit1', 'Digit2', 'Digit3'];
