let musT = 1.2;
function musicUpd(dt) {
  if (Snd.muted || state === 'paused') return;
  musT -= dt;
  if (musT > 0) return;
  musT = state === 'playing' ? rand(1.2, 2.4) : rand(1.5, 3);
  const a = irand(2, 8), r = Math.random();
  Snd.phrase(r < 0.3 ? [a, clamp(a + pick([-2, -1, 1, 2]), 2, 9)] : r < 0.42 ? [pick([0, 1]), a, clamp(a + 1, 2, 9)] : [a]);
}

/* ==================== 13. autoplay bot ==================== */
function botUpd(dt) {
  botT -= dt;
  if (botT > 0) return;
  for (const e of ENTS) {
    if (!e.on || e.bomb || e.float || e.age < 0.3 || e.y > H - 60 || e.y < 40) continue;
    const a = rand(-1.2, 1.2), L = e.r + 30;
    const ax = e.x - Math.cos(a) * L, ay = e.y - Math.sin(a) * L, bx = e.x + Math.cos(a) * L, by = e.y + Math.sin(a) * L;
    let bad = false;
    for (const b of ENTS) if (b.on && b.bomb && segDist2(b.x, b.y, ax, ay, bx, by) < (b.r + 12) * (b.r + 12)) bad = true;
    if (bad) continue;
    const now = performance.now();
    ghostTrail.pts.length = 0; trailAdd(ghostTrail, ax, ay, now - 50); trailAdd(ghostTrail, e.x, e.y, now - 25); trailAdd(ghostTrail, bx, by, now);
    bladeSeg(ax, ay, bx, by, 2200, 'b');
    botT = rand(0.05, 0.14);
    break;
  }
}

/* ==================== 14. main loop ==================== */
let lastT = performance.now();
function step(dt, now) {
  realT += dt;
  switch (state) {
    case 'title': titleUpd(dt); worldUpd(dt); break;
    case 'help': if (helpFrom === 'title') { titleUpd(dt); worldUpd(dt); } break;
    case 'countdown': countdownUpd(dt); worldUpd(dt); break;
    case 'playing': playUpd(dt); break;
    case 'ending': endingUpd(dt); break;
    case 'over': worldUpd(dt); if (nbT >= 0) nbT += dt; break;
  }
  const frozen = state === 'paused' || (state === 'help' && helpFrom === 'paused');
  if (!frozen) {
    updHalves(MHALVES, dt); updDrops(MDROPS, dt); updPops(dt); ghostUpd(dt);
    if (menuPending) { menuPending.t -= dt; if (menuPending.t <= 0) { const f = menuPending.fn; menuPending = null; f(); } }
  }
  trailDraw(trail, now); trailDraw(ghostTrail, now);
  hudUpd(dt); ovUpd(dt); shakeUpd(dt); fxUpd(); musicUpd(dt); lanternUpd(dt);
  Snd.hiss(state === 'playing' && bombsOn > 0);
}
function frame(now) {
  requestAnimationFrame(frame);
  let dt = (now - lastT) / 1000;
  lastT = now;
  if (!(dt > 0)) dt = 0;
  if (dt > 1 / 30) dt = 1 / 30;
  step(dt, now);
}

/* ==================== 15. test hooks ==================== */
window.__GAME__ = {
  get state() { return state; },
  get score() { return score; },
  get mode() { return MODES[mode].key; },
  get difficulty() { return diff; },
  start(d, m) {
    const mi = typeof m === 'string' ? Math.max(0, MODES.findIndex((x) => x.key === m)) : m == null ? selMode : clamp(m | 0, 0, 2);
    startRun(mi, clamp(d == null ? 1 : d | 0, 0, 2), true);
    return state;
  },
  debug: {
    // dispatch real synthetic pointer events along a polyline (viewBox coords) over ms milliseconds
    swipe(points, ms) {
      ms = ms || 120;
      return new Promise((res) => {
        const m = svg.getScreenCTM();
        if (!m || !points || points.length < 2) { res(null); return; }
        const toC = (p) => ({ x: m.a * p[0] + m.c * p[1] + m.e, y: m.b * p[0] + m.d * p[1] + m.f });
        const s0 = fruitsSliced, b0 = bombsHit, steps = Math.max(2, Math.round(ms / 16)), segs = points.length - 1, pts = [];
        for (let i = 0; i <= steps; i++) {
          const f = i / steps * segs, k = Math.min(segs - 1, Math.floor(f)), u = f - k;
          pts.push([lerp(points[k][0], points[k + 1][0], u), lerp(points[k][1], points[k + 1][1], u)]);
        }
        const fire = (type, p) => {
          const c = toC(p);
          svg.dispatchEvent(new PointerEvent(type, { clientX: c.x, clientY: c.y, pointerId: 7, pointerType: 'mouse', isPrimary: true, button: 0, buttons: type === 'pointerup' ? 0 : 1, bubbles: true, cancelable: true }));
        };
        fire('pointerdown', pts[0]);
        let i = 1;
        const t0 = performance.now();
        const tick = () => {
          const k = Math.min(pts.length - 1, Math.floor((performance.now() - t0) / ms * steps));
          while (i <= k) { fire('pointermove', pts[i]); i++; }
          if (i < pts.length) setTimeout(tick, 8);
          else { fire('pointerup', pts[pts.length - 1]); res({ sliced: fruitsSliced - s0, bombs: bombsHit - b0, state, score }); }
        };
        setTimeout(tick, 8);
      });
    },
    slash(ax, ay, bx, by) { bladeSeg(ax, ay, bx, by, 2500, 'p'); endCombo(); return { state, score, sliced: fruitsSliced }; },
    spawn(kind, x, y, o) {
      o = o || {};
      const moving = o.vx != null || o.vy != null;
      return !!spawnEnt(kind, x, y, o.vx || 0, o.vy || 0, { float: o.float != null ? o.float : !moving, nomiss: o.nomiss });
    },
    spawnFruit(t, x, y, o) { return this.spawn(t || pick(TYPES), x, y, o); },
    spawnBomb(x, y, o) { return this.spawn('bomb', x, y, o); },
    flood(n) { for (let i = 0; i < n; i++) spawnEnt(TYPES[i % 10], rand(120, 1160), rand(160, 560), rand(-25, 25), rand(-15, 15), { float: 1, nomiss: 1 }); return ENTS.filter((e) => e.on).length; },
    splatters(n) { for (let i = 0; i < n; i++) { const t = pick(TYPES); decal(rand(60, 1220), rand(60, 660), FR[t].s, rand(0.8, 1.6), 0.6, 40); } return DECALS.filter((d) => d.on).length; },
    fastForward(sec) { const n = Math.round(sec * 60); for (let i = 0; i < n; i++) step(1 / 60, performance.now()); return { state, score }; },
    setTime(t) { timeLeft = t; return timeLeft; },
    get autoplay() { return bot; }, set autoplay(v) { bot = !!v; },
    get god() { return god; }, set god(v) { god = !!v; },
    lose() { if (state === 'playing') gameOver(MODES[mode].time ? 'time' : 'miss'); return state; },
    info() {
      const c = (a) => a.filter((x) => x.on).length;
      return { state, mode: MODES[mode].key, diff, score, misses, fruitsSliced, fruitsMissed, bestCombo, bestStreak, crits, streak, timeLeft: +timeLeft.toFixed(2), ents: c(ENTS), bombs: bombsOn, halves: c(HALVES), drops: c(DROPS), decals: c(DECALS), pw: Object.assign({}, pw), muted: Snd.muted, best: best.slice() };
    }
  }
};

/* ==================== 16. init ==================== */
for (let i = 0; i < 3; i++) $('best' + i).textContent = '最高 ' + best[i];
selectMode(0); setDiff(1);
$('muteIco').setAttribute('href', Snd.muted ? '#icoMute' : '#icoSound');
setState('title');
requestAnimationFrame((t) => { lastT = t; requestAnimationFrame(frame); });
})();
